csui.define('dctmw/utils/perspectives/app.scope.perspectives',[
  'nuc/lib/underscore',
  'dctmw/utils/perspectives/app.scope.collection',
  'dctm-ext!dctmw/utils/perspectives/app.scope.perspectives'
], function (_, D2ApplicationScopeCollection, extAppScopes) {
  'use strict';

  var appScopePerspectives = new D2ApplicationScopeCollection();

  var appScopes = [];

  if (extAppScopes) {
    appScopes = appScopes.concat(_.flatten(extAppScopes, true));
  }

  appScopePerspectives.add(appScopes);

  return appScopePerspectives;
});
