csui.define('dctmw/server.adaptors/models/csui/models/widget/search.results/search.settings/server.adaptor.mixin',[
  'nuc/lib/underscore',
  'nuc/lib/jquery'
], function(_, $){
  'use strict';
  
  const ServerAdaptorMixin = {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },
        
        sync: function (method, model, options={}) {
          const dfd = $.Deferred();
          this.trigger('request', this, {}, options);
          setTimeout(function(){
            const response = {};
            options.success.call(options.context, {}, 'success', response);
            dfd.resolve(response);
          }, 1);
          return dfd.promise();
        }
      });
    }
  };
  
  return ServerAdaptorMixin;
});