csui.define('dctmw/utils/theme/theme.config.manager',[
  'nuc/lib/jquery',
  'nuc/lib/backbone'
], function($, Backbone){

  class ThemeConfigModel extends Backbone.Model {
    constructor(attr, options={}) {
      super(attr, options);
    }

    fetch() {
      return $.Deferred().resolve().promise();
    }
  }

  return {
    initAppPageStyles: function(/*context*/) {

    },

    getDefaultThemeModel: function(/*context*/) {
      return new ThemeConfigModel();
    },
    
    getUserThemeModel: function(/*context*/) {
      return new ThemeConfigModel();
    }
  };
});